package handlers

imports: encoding/base64, encoding/json, fmt, net/http, strconv

func EncodeCursor(id string) string:
  return base64.StdEncoding.EncodeToString([]byte(id))

func DecodeCursor(cursor string) (string, error):
  decoded, err := base64.StdEncoding.DecodeString(cursor)
  if err: return "", fmt.Errorf("invalid cursor: %w", err)
  return string(decoded), nil

type PaginatedResponse struct {
  Items      []Item `json:"items"`
  NextCursor string `json:"nextCursor,omitempty"`
  HasMore    bool   `json:"hasMore"`
}

func (s *ItemStore) ListHandler(w, r):
  // Parse limit: default 20, max 100, validate 1-100
  limitStr := r.URL.Query().Get("limit")
  limit := 20
  if limitStr != "":
    parsed, err := strconv.Atoi(limitStr)
    if err or parsed < 1 or parsed > 100: respond 400, return
    limit = parsed

  // Parse cursor: if provided, decode to get startAfterID
  cursorStr := r.URL.Query().Get("cursor")
  var startAfterID string
  if cursorStr != "":
    decoded, err := DecodeCursor(cursorStr)
    if err: respond 400 "invalid cursor", return
    startAfterID = decoded

  // Get all items, find start position
  allItems := s.All()
  startIdx := 0
  if startAfterID != "":
    for i, item := range allItems:
      if item.ID == startAfterID: startIdx = i + 1; break

  // Slice items for this page
  endIdx := startIdx + limit
  if endIdx > len(allItems): endIdx = len(allItems)
  pageItems := allItems[startIdx:endIdx]
  hasMore := endIdx < len(allItems)

  // Build response
  resp := PaginatedResponse{Items: pageItems, HasMore: hasMore}
  if hasMore and len(pageItems) > 0:
    resp.NextCursor = EncodeCursor(pageItems[len(pageItems)-1].ID)

  w.Header().Set("Content-Type", "application/json")
  json.NewEncoder(w).Encode(resp)
